        for (Reservation res : reservations) {
            BigDecimal amount = res.amountPaid;
            if (res.refund != null) {
                amount = amount.subtract(res.refund);
            }
            total = total.add(amount);
        }

        return "total," + currencyFormatter.format(total);
    }
}

